{
  "userQuery": "下午茶拼单卡片,主体用🥤🧋这种字符当大图标,旁边环形显示还差几人成团。要跳到天气看今天适不适合送到户外,顺便读日历看大家有没有会耽误收餐。浅色底,渐变用那种运动紧迫感的橙红色,代表快截止了。接近阈值的提醒要明显。列表可滚动,字符做图标。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "拼单卡片标题",
        "sampleValue": "下午茶团"
      }
    },
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "拼单群组图标资源路径",
        "sampleValue": "resources/base/media/person_3_fill.svg"
      },
      "actionIcon": {
        "type": "string",
        "description": "天气跳转入口图标资源路径",
        "sampleValue": "resources/base/media/cloudy_turning_sunny.png"
      }
    },
    "group": {
      "iconGlyph": {
        "type": "string",
        "description": "下午茶字符图标文本",
        "sampleValue": "饮"
      },
      "joinedCount": {
        "type": "number",
        "description": "当前已参团人数",
        "sampleValue": 4
      },
      "targetCount": {
        "type": "number",
        "description": "成团目标人数",
        "sampleValue": 6
      },
      "remainingCount": {
        "type": "number",
        "description": "距离成团还差的人数",
        "sampleValue": 2
      },
      "deadlineText": {
        "type": "string",
        "description": "拼单截止时间短文本",
        "sampleValue": "18:00截"
      }
    },
    "data": {
      "weather": {
        "current": {
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      },
      "calendar": {
        "items": [
          {
            "dtStart": {
              "type": "string",
              "description": "今日首个可能影响收餐的日程开始时间",
              "sampleValue": "14:30"
            },
            "title": {
              "type": "string",
              "description": "今日首个可能影响收餐的日程标题",
              "sampleValue": "评审会"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/person_3_fill.svg",
      "description": "三人组实心图标，适合表达拼单团购的群组人数与成团语义。",
      "bindTo": "/asset/primaryIcon"
    },
    {
      "src": "resources/base/media/cloudy_turning_sunny.png",
      "description": "云朵和太阳组合的彩色天气图标，适合用于跳转天气查看户外配送条件。",
      "bindTo": "/asset/actionIcon"
    }
  ]
}

